SELECT student_id
FROM enrollment
WHERE course_id = #{courseId}

SELECT * FROM ( SELECT c.id AS course_id, d.dept_name AS dept_name, p.id AS professor_id, s.name AS subject_name, u.name AS professor_name, sem.name AS semester_name, c.capacity AS capacity, c.num_of_student AS num_of_student, c.day_of_week AS day_of_week, c.time AS time, c.place AS place, c.status AS status, s.credit AS credit,
CASE WHEN EXISTS ( SELECT 1 FROM enrollment e WHERE e.course_id = c.id AND e.student_id = #{studentId} ) THEN 1 ELSE 0 END AS isEnrolled,
ROW_NUMBER() OVER (ORDER BY c.id DESC) AS rn FROM course c JOIN subject s ON c.subject_id = s.id JOIN dept d ON s.dept_id = d.id JOIN professor p ON c.professor_id = p.id JOIN users u ON p.user_id = u.id JOIN semester sem ON c.semester_id = sem.id WHERE c.semester_id = #{currentSemesterId} AND c.status = 'OPEN'
) WHERE rn BETWEEN #{pageRequestDTO.start} AND #{pageRequestDTO.end}

SELECT id, course_id, student_id
FROM enrollment
WHERE id = #{id}

SELECT id, course_id, student_id
FROM enrollment
WHERE course_id = #{courseId}
